/* ===== OpenLearnHub — Shared Styles ===== */

:root {
  --navy: #0A0A23;
  --navy-light: #1A1A3E;
  --gold: #FEAC32;
  --gold-dark: #E09A1E;
  --link-blue: #002EAD;
  --white: #FFFFFF;
  --gray-50: #F8F9FA;
  --gray-100: #F0F0F5;
  --gray-200: #E0E0E8;
  --gray-300: #C0C0CC;
  --gray-400: #90909E;
  --gray-500: #6B6B7B;
  --gray-600: #4A4A5A;
  --gray-700: #2E2E3E;
  --gray-800: #1B1B2E;
  --radius: 8px;
  --radius-lg: 12px;
  --shadow: 0 2px 8px rgba(0,0,0,0.08);
  --shadow-lg: 0 4px 24px rgba(0,0,0,0.12);
  --transition: 0.2s ease;
  --max-width: 1200px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { font-size: 16px; scroll-behavior: smooth; }

body {
  font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  color: var(--gray-800);
  background: var(--gray-50);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
ul { list-style: none; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }
input { font-family: inherit; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* ===== Header ===== */
.header {
  background: var(--navy);
  color: var(--white);
  position: sticky;
  top: 0;
  z-index: 100;
}
.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 56px;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  gap: 24px;
}
.header-left { display: flex; align-items: center; gap: 16px; flex-shrink: 0; }
.logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--white);
}
.logo-icon {
  width: 32px;
  height: 32px;
  background: var(--gold);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 0.9rem;
  color: var(--navy);
}
.search-wrap {
  flex: 1;
  max-width: 480px;
  position: relative;
}
.search-wrap input {
  width: 100%;
  height: 36px;
  border-radius: 20px;
  border: none;
  padding: 0 16px 0 38px;
  font-size: 0.875rem;
  background: var(--navy-light);
  color: var(--white);
  outline: none;
  transition: var(--transition);
}
.search-wrap input::placeholder { color: var(--gray-400); }
.search-wrap input:focus { background: #252550; box-shadow: 0 0 0 2px var(--gold); }
.search-icon {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--gray-400);
  pointer-events: none;
}
.header-nav { display: flex; align-items: center; gap: 20px; flex-shrink: 0; }
.header-nav a {
  color: var(--gray-300);
  font-size: 0.9rem;
  font-weight: 500;
  transition: var(--transition);
  padding: 4px 0;
}
.header-nav a:hover, .header-nav a.active { color: var(--white); }
.header-nav a.donate-btn {
  background: var(--gold);
  color: var(--navy);
  padding: 6px 16px;
  border-radius: 20px;
  font-weight: 600;
  font-size: 0.85rem;
  transition: var(--transition);
}
.header-nav a.donate-btn:hover { background: var(--gold-dark); }

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 4px;
  background: none;
  border: none;
  cursor: pointer;
  z-index: 110;
}
.hamburger span {
  display: block;
  width: 22px;
  height: 2px;
  background: var(--white);
  border-radius: 2px;
  transition: var(--transition);
}
.hamburger.active span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
.hamburger.active span:nth-child(2) { opacity: 0; }
.hamburger.active span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

/* Mobile nav */
.mobile-nav {
  display: none;
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--navy);
  z-index: 105;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 32px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s ease;
}
.mobile-nav.active { opacity: 1; pointer-events: all; }
.mobile-nav a {
  color: var(--white);
  font-size: 1.5rem;
  font-weight: 600;
  transition: var(--transition);
}
.mobile-nav a:hover { color: var(--gold); }
.mobile-nav a.donate-btn {
  background: var(--gold);
  color: var(--navy);
  padding: 12px 32px;
  border-radius: 24px;
  font-size: 1.25rem;
}

/* ===== Banner ===== */
.banner {
  background: var(--navy-light);
  color: var(--white);
  text-align: center;
  padding: 12px 24px;
  font-size: 0.95rem;
  font-weight: 500;
}
.banner a {
  color: var(--gold);
  text-decoration: underline;
  font-weight: 600;
}
.banner a:hover { color: var(--gold-dark); }

/* ===== Featured Article ===== */
.featured {
  padding: 48px 0 40px;
}
.featured-card {
  display: grid;
  grid-template-columns: 1fr 1fr;
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow);
  transition: var(--transition);
}
.featured-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-2px); }
.featured-thumb {
  position: relative;
  min-height: 320px;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}
.featured-thumb svg { width: 120px; height: 120px; opacity: 0.3; }
.featured-content {
  padding: 40px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.featured-content .tag { margin-bottom: 16px; }
.featured-content h2 {
  font-size: 1.75rem;
  font-weight: 700;
  line-height: 1.3;
  margin-bottom: 20px;
  color: var(--gray-800);
}

/* ===== Tags ===== */
.tag {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  padding: 4px 10px;
  border-radius: 4px;
  transition: var(--transition);
}
.tag:hover { opacity: 0.85; }
.tag-ai { background: #EDE9FE; color: #6D28D9; }
.tag-web-scraping { background: #FCE7F3; color: #BE185D; }
.tag-databases { background: #DCFCE7; color: #15803D; }
.tag-elasticsearch { background: #FEF3C7; color: #B45309; }
.tag-data-engineering { background: #E0F2FE; color: #0369A1; }
.tag-javascript { background: #FEF3C7; color: #B45309; }
.tag-python { background: #DBEAFE; color: #1D4ED8; }
.tag-css { background: #FCE7F3; color: #BE185D; }
.tag-react { background: #E0F2FE; color: #0369A1; }
.tag-node { background: #DCFCE7; color: #15803D; }
.tag-ai-automation { background: #EDE9FE; color: #6D28D9; }
.tag-google-sheets { background: #DCFCE7; color: #15803D; }

/* ===== Author ===== */
.author {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 0.85rem;
  color: var(--gray-500);
}
.author-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 0.7rem;
  color: var(--gray-600);
  flex-shrink: 0;
}
.author-name { font-weight: 600; color: var(--gray-700); }

/* ===== Section Headers ===== */
.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 28px;
}
.section-title {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--gray-800);
}
.section-link {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--link-blue);
  transition: var(--transition);
}
.section-link:hover { text-decoration: underline; }

/* ===== Article Grid ===== */
.articles-section { padding: 0 0 48px; }
.article-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.article-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow);
  transition: var(--transition);
  display: flex;
  flex-direction: column;
}
.article-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-2px); }
.article-card-thumb {
  width: 100%;
  height: 180px;
  position: relative;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}
.article-card-thumb svg { width: 64px; height: 64px; opacity: 0.4; }
.article-card-body { padding: 20px; flex: 1; display: flex; flex-direction: column; }
.article-card-body .tag { margin-bottom: 12px; width: fit-content; }
.article-card-body h3 {
  font-size: 1.1rem;
  font-weight: 700;
  line-height: 1.4;
  margin-bottom: 16px;
  flex: 1;
  color: var(--gray-800);
  transition: var(--transition);
}
.article-card:hover h3 { color: var(--link-blue); }

/* ===== Load More ===== */
.load-more-wrap { text-align: center; padding: 8px 0 48px; }
.btn-load-more {
  display: inline-block;
  padding: 12px 32px;
  background: var(--navy);
  color: var(--white);
  font-size: 0.95rem;
  font-weight: 600;
  border-radius: 24px;
  transition: var(--transition);
}
.btn-load-more:hover { background: var(--navy-light); transform: translateY(-1px); }

/* ===== Page Hero (Donate, Learn) ===== */
.page-hero {
  padding: 64px 0 48px;
  text-align: center;
}
.page-hero h1 {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--gray-800);
  margin-bottom: 16px;
  line-height: 1.2;
}
.page-hero p {
  font-size: 1.15rem;
  color: var(--gray-500);
  max-width: 640px;
  margin: 0 auto;
  line-height: 1.7;
}

/* ===== Learn Page ===== */
.learn-section { padding: 0 0 56px; }
.welcome-cta {
  text-align: center;
  padding: 20px 0 40px;
}
.welcome-cta p {
  font-size: 1.1rem;
  color: var(--gray-500);
}
.welcome-cta a {
  color: var(--link-blue);
  font-weight: 600;
}
.welcome-cta a:hover { text-decoration: underline; }

.curriculum-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
}
.curriculum-card {
  display: flex;
  align-items: flex-start;
  gap: 18px;
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow);
  transition: var(--transition);
  border-left: 4px solid transparent;
}
.curriculum-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
  border-left-color: var(--gold);
}
.curriculum-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius);
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 1.4rem;
}
.curriculum-info h4 {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--gray-800);
  margin-bottom: 4px;
}
.curriculum-info span {
  font-size: 0.85rem;
  color: var(--gray-400);
}

.resource-section { padding: 0 0 56px; }
.resource-section h3 {
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--gray-800);
  margin-bottom: 20px;
}
.resource-list {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
}
.resource-item {
  background: var(--white);
  border-radius: var(--radius);
  padding: 16px 20px;
  font-weight: 600;
  font-size: 0.95rem;
  color: var(--gray-700);
  box-shadow: var(--shadow);
  transition: var(--transition);
}
.resource-item:hover {
  color: var(--link-blue);
  box-shadow: var(--shadow-lg);
}

.daily-challenge {
  background: linear-gradient(135deg, var(--navy), var(--navy-light));
  color: var(--white);
  border-radius: var(--radius-lg);
  padding: 40px;
  margin-bottom: 48px;
  text-align: center;
}
.daily-challenge h3 { font-size: 1.4rem; margin-bottom: 20px; }
.daily-challenge-links { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }
.daily-challenge-links a {
  display: inline-block;
  padding: 10px 24px;
  border-radius: 24px;
  font-weight: 600;
  font-size: 0.9rem;
  transition: var(--transition);
}
.daily-challenge-links a:first-child {
  background: var(--gold);
  color: var(--navy);
}
.daily-challenge-links a:first-child:hover { background: var(--gold-dark); }
.daily-challenge-links a:last-child {
  background: transparent;
  color: var(--white);
  border: 2px solid rgba(255,255,255,0.3);
}
.daily-challenge-links a:last-child:hover { border-color: var(--white); }

/* ===== Donate Page ===== */
.donate-hero {
  padding: 64px 0 48px;
  text-align: center;
}
.donate-hero h1 {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--gray-800);
  margin-bottom: 20px;
}
.donate-hero .hero-body {
  font-size: 1.15rem;
  color: var(--gray-500);
  max-width: 680px;
  margin: 0 auto 0;
  line-height: 1.7;
}

.donate-form-section { padding: 0 0 48px; }
.donate-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 40px;
  box-shadow: var(--shadow);
  max-width: 560px;
  margin: 0 auto;
}
.amount-label {
  font-size: 1rem;
  font-weight: 600;
  color: var(--gray-600);
  margin-bottom: 16px;
}
.amount-tabs {
  display: flex;
  gap: 12px;
  margin-bottom: 20px;
}
.amount-tab {
  flex: 1;
  padding: 14px 12px;
  border: 2px solid var(--gray-200);
  border-radius: var(--radius);
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--gray-600);
  background: var(--white);
  transition: var(--transition);
  text-align: center;
}
.amount-tab:hover { border-color: var(--gold); color: var(--gray-800); }
.amount-tab.active {
  border-color: var(--gold);
  background: #FFF8E7;
  color: var(--navy);
}
.donate-description {
  font-size: 0.95rem;
  color: var(--gray-500);
  margin-bottom: 24px;
  line-height: 1.5;
}
.btn-donate {
  display: block;
  width: 100%;
  padding: 14px;
  background: var(--gold);
  color: var(--navy);
  font-size: 1.1rem;
  font-weight: 700;
  border-radius: 24px;
  transition: var(--transition);
  margin-bottom: 12px;
}
.btn-donate:hover { background: var(--gold-dark); }
.donate-sub-label {
  text-align: center;
  font-size: 0.85rem;
  color: var(--gray-400);
}

.benefits-section { padding: 0 0 48px; }
.benefits-section h2, .initiatives-section h2, .achievements-section h2, .faq-section h2 {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--gray-800);
  margin-bottom: 24px;
  text-align: center;
}
.benefits-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 16px;
  max-width: 800px;
  margin: 0 auto;
}
.benefit-item {
  display: flex;
  align-items: center;
  gap: 14px;
  background: var(--white);
  border-radius: var(--radius);
  padding: 18px 22px;
  box-shadow: var(--shadow);
  font-weight: 500;
  color: var(--gray-700);
}
.benefit-check {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: #DCFCE7;
  color: #15803D;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 0.8rem;
  flex-shrink: 0;
}

.initiatives-section { padding: 0 0 48px; }
.initiative-list {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
  max-width: 800px;
  margin: 0 auto;
}
.initiative-item {
  background: var(--white);
  border-radius: var(--radius);
  padding: 20px 24px;
  box-shadow: var(--shadow);
  font-weight: 500;
  color: var(--gray-700);
  transition: var(--transition);
}
.initiative-item:hover { box-shadow: var(--shadow-lg); }

.achievements-section { padding: 0 0 48px; }
.achievement-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 20px;
  max-width: 1000px;
  margin: 0 auto;
}
.achievement-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 28px 24px;
  text-align: center;
  box-shadow: var(--shadow);
}
.achievement-number {
  font-size: 2rem;
  font-weight: 800;
  color: var(--navy);
  margin-bottom: 8px;
}
.achievement-label { font-size: 0.9rem; color: var(--gray-500); line-height: 1.4; }

/* ===== FAQ Accordion ===== */
.faq-section { padding: 0 0 64px; }
.faq-list { max-width: 760px; margin: 0 auto; }
.faq-item {
  background: var(--white);
  border-radius: var(--radius);
  margin-bottom: 8px;
  box-shadow: var(--shadow);
  overflow: hidden;
}
.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 24px;
  text-align: left;
  font-size: 1rem;
  font-weight: 600;
  color: var(--gray-800);
  transition: var(--transition);
}
.faq-question:hover { color: var(--navy); }
.faq-arrow {
  flex-shrink: 0;
  margin-left: 16px;
  transition: transform 0.3s ease;
  font-size: 0.8rem;
  color: var(--gray-400);
}
.faq-item.open .faq-arrow { transform: rotate(180deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.35s ease;
}
.faq-item.open .faq-answer {
  max-height: 300px;
  padding: 0 24px 20px;
}
.faq-answer p {
  font-size: 0.95rem;
  color: var(--gray-500);
  line-height: 1.7;
}

/* ===== Tag Page ===== */
.tag-page-header {
  padding: 48px 0 16px;
  text-align: center;
}
.tag-page-header h1 {
  font-size: 2rem;
  font-weight: 800;
  color: var(--gray-800);
  margin-bottom: 8px;
}
.tag-page-header .tag-count {
  font-size: 1.1rem;
  color: var(--gray-500);
}
.popular-tags-section { padding: 24px 0 16px; }
.popular-tags-section h3 {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--gray-700);
  margin-bottom: 16px;
}
.popular-tags-scroll {
  display: flex;
  gap: 12px;
  overflow-x: auto;
  padding-bottom: 8px;
  -webkit-overflow-scrolling: touch;
}
.popular-tags-scroll::-webkit-scrollbar { height: 4px; }
.popular-tags-scroll::-webkit-scrollbar-thumb { background: var(--gray-300); border-radius: 4px; }
.popular-tag-chip {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 24px;
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--gray-700);
  white-space: nowrap;
  transition: var(--transition);
  flex-shrink: 0;
}
.popular-tag-chip:hover { border-color: var(--gold); color: var(--navy); }
.popular-tag-chip .chip-count {
  font-size: 0.75rem;
  color: var(--gray-400);
  font-weight: 500;
}

/* ===== Footer ===== */
.footer {
  background: var(--gray-100);
  border-top: 1px solid var(--gray-200);
  padding: 56px 0 40px;
  margin-top: 16px;
}
.footer-mission {
  max-width: 720px;
  margin-bottom: 32px;
  font-size: 0.95rem;
  color: var(--gray-500);
  line-height: 1.7;
}
.footer-mission strong { color: var(--gray-700); }
.footer h4 {
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--gray-500);
  margin-bottom: 12px;
}
.trending-guides {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 16px;
  margin-bottom: 32px;
}
.trending-guides a {
  font-size: 0.875rem;
  color: var(--gray-600);
  transition: var(--transition);
}
.trending-guides a:hover { color: var(--link-blue); }
.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 24px;
  padding-top: 24px;
  border-top: 1px solid var(--gray-200);
}
.footer-links a {
